      "[因斯·赞格威尔](../因斯·赞格威尔/)留下的故事记载，他将一半死神后裔特性提前植入梅高欧丝体内，使她能够承受后续仪式。这是被外力植入的特性，不能直接等同于她通过魔药晋升的个人途径。见《诡秘之主》第一部第210章 故事。"
