    "documentProfile": [
      "所属组织：血之上将麾下（推测）。他与血之上将二副麦维提共同执行追捕行动，据此推断隶属该海盗团；具体身份待核。（《诡秘之主》第三部第36章 人之将死、第43章 冷静的斯考尔）",
      "国籍：鲁恩（相遇地暂定）。[阿尔杰](../阿尔杰·威尔逊/)在鲁恩殖民地拜亚姆与斯考尔相见。这不构成法律国籍证明。（《诡秘之主》第三部第43章 冷静的斯考尔）"
    ],
    "pathwayPeriodNotes": [
      "斯考尔下压双掌时，[克莱恩](../克莱恩·莫雷蒂/)身体变沉、动作放缓，变成纸人后又被无形力量压向地面；斯考尔死后有非凡特性析出。同一场交战中，他发出尖啸所用的符咒由血之上将制作。他在战斗中表现得冷静而残酷；《恶魔学》描述[罪犯途径](../../../worldview/pathways/罪犯途径/罪犯途径.html)序列8“冷血者”（又称“折翼天使”）冷静冷酷，能获得因人而异的恶魔领域类法术。结合这些线索，可推测他属于该途径和序列，但原文未直接确认。见《诡秘之主》第三部第43章 冷静的斯考尔、第45章 速战；《宿命之环》第四部第142章 宣泄。参考：[诡秘之主 Wiki 对斯考尔途径的推测](https://lordofthemysteries.fandom.com/zh/wiki/%E6%96%AF%E8%80%83%E5%B0%94)。"
    ],
