      "国籍：[费内波特](../../../worldview/countries/entries/费内波特.html)（推定）。卢米安在费内波特桑塔港陪同玛尔塔及帕科一家前往“海之总督”府邸；国籍仅为暂定，原文未明确法律国籍。依据：《宿命之环》第四部第54章 “海之总督”。"
