    "pathwayPeriodNotes": [
      "[卢米安](../卢米安·李/)调查帕科家族时，认为昔日“海之侍女”玛尔塔身上仍残留大海的力量。后文揭示，她在第54章随鲁维奥去见海之总督时已是洛基的秘偶；第69章的判断发生在她被操纵期间。她本人的具体序列未明。见《宿命之环》第四部第69章 再试一试、第84章 秘偶。",
      "成为洛基的秘偶后，玛尔塔在战斗中展现了大海血统相关的射线能力。她出现前，现场已被“虚无星空”笼罩；这场战斗不能单独证明她本人的途径或序列。见《宿命之环》第四部第84章 秘偶。"
    ],
