    "classificationEvidence": [],
    "documentProfile": [
      "国籍：待核实。因蒂斯集团是梦境中的工作单位，后续现身的是借用黄总形象的镜中罗塞尔，梦中任职没有给出梦外籍贯。（《宿命之环》第六部第85章 “阴谋家”的嗅觉、第139章 三句话）"
    ],
    "pathwayPeriodNotes": [
      "黄总是罗塞尔在梦境都市的形象；卢米安等人认为镜中的罗塞尔曾尝试占据这一身份，并指出后者是[窥秘人途径](../../../worldview/pathways/窥秘人途径/窥秘人途径.html)的天使。这个梦境身份受到外来影响，不能把镜中人的序列或罗塞尔本人的晋升经历直接记为黄总自身的序列。见《宿命之环》第六部第85章 “阴谋家”的嗅觉、第127章 再入梦境。"
    ],
    "documentProfileUrl": "../characters/entries/%E9%BB%84%E6%80%BB%EF%BC%88%E6%A2%A6%E5%A2%83%E9%83%BD%E5%B8%82%EF%BC%89/"
